  "candidates": [
    {
      "label": "A",
      "phrases": [
        {
          "id": "V2-01",
          "zh": "晨光为什么落在我肩上"
        },
        {
          "id": "V2-02",
          "zh": "夜色为什么让人心发慌"
        },
        {
          "id": "V2-03",
          "zh": "悲伤分我一半好不好"
        },
        {
          "id": "V2-04",
          "zh": "若能这样该多好"
        }
      ]
    },
    {
      "label": "B",
      "phrases": [
        {
          "id": "V2-01",
          "zh": "为何晨光总将我照亮？"
        },
        {
          "id": "V2-02",
          "zh": "为何夜晚总让人心伤？"
        },
        {
          "id": "V2-03",
          "zh": "悲伤的事各分一半"
        },
        {
          "id": "V2-04",
          "zh": "若能那样该多好"
        }
      ]
    }
  ]
